+    @Test
+    void testDelayedEmptyRequestBody() throws Exception {
+        sendDelayedRequestBody("");
+    }
+
+    @Test
+    void testDelayedRequestBody() throws Exception {
+        sendDelayedRequestBody("Un soir, t'en souvient-il? nous voguions en silence");
+    }
